/**
 * Example: Using Design System Tokens in Figma Plugin
 *
 * This example shows how to fetch and use the design tokens in a Figma plugin.
 * The tokens.json file is generated by the build process and served from the public directory.
 */

// Configuration
const TOKENS_URL = 'https://your-domain.com/tokens.json'; // Update with your domain

/**
 * Fetch design tokens from the server
 */
async function loadDesignTokens() {
  try {
    console.log('Fetching design tokens...');
    const response = await fetch(TOKENS_URL);

    if (!response.ok) {
      throw new Error(`HTTP error! status: ${response.status}`);
    }

    const tokensData = await response.json();
    console.log(
      `✅ Loaded ${tokensData.meta.totalTokens} tokens (v${tokensData.meta.version})`
    );
    console.log(`Generated: ${tokensData.meta.generatedAt}`);

    return tokensData;
  } catch (error) {
    console.error('❌ Error loading design tokens:', error);
    throw error;
  }
}

/**
 * Create Figma color styles from tokens
 */
async function createColorStyles() {
  const figma = (window).figma;
  const tokensData = await loadDesignTokens();

  const { sections } = tokensData;

  for (const section of sections) {
    console.log(`Processing section: ${section.title}`);

    for (const token of section.tokens) {
      try {
        // Parse hex color to RGB
        const color = hexToRgb(token.hex);
        if (!color) {
          console.warn(`Invalid color for token ${token.name}: ${token.hex}`);
          continue;
        }

        // Create color style
        const paint = {
          type: 'SOLID',
          color: {
            r: color.r / 255,
            g: color.g / 255,
            b: color.b / 255,
          },
        };

        // Create Figma style
        const style = figma.createPaintStyle();
        style.name = `${section.title}/${token.name}`;
        style.paints = [paint];

        console.log(`✅ Created style: ${style.name}`);
      } catch (error) {
        console.error(`Error creating style for ${token.name}:`, error);
      }
    }
  }

  console.log('✅ Color styles created successfully!');
}

/**
 * Convert hex color to RGB
 */
function hexToRgb(hex) {
  const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
  return result
    ? {
        r: parseInt(result[1], 16),
        g: parseInt(result[2], 16),
        b: parseInt(result[3], 16),
      }
    : null;
}

