/**
 * List all available tokens
 */
async function listTokens() {
  const tokensData = await loadDesignTokens();
  const { sections, meta } = tokensData;

  console.log('\n=== DESIGN SYSTEM TOKENS ===');
  console.log(`Version: ${meta.version}`);
  console.log(`Generated: ${meta.generatedAt}`);
  console.log(`Total Tokens: ${meta.totalTokens}`);
  console.log(`\nToken Sections:`);

  sections.forEach((section) => {
    console.log(`\n${section.title} (${section.tokens.length} tokens)`);
    console.log(`Description: ${section.description}`);
    section.tokens.slice(0, 3).forEach((token) => {
      console.log(`  - ${token.name}: ${token.hex}`);
    });
    if (section.tokens.length > 3) {
      console.log(`  ... and ${section.tokens.length - 3} more`);
    }
  });
}

/**
 * Export tokens in Figma-compatible format
 */
async function exportFigmaJSON() {
  const tokensData = await loadDesignTokens();
  const { sections } = tokensData;

  // Convert to Figma tokens format (Design Tokens plugin format)
  const figmaTokens = {
    global: {},
    sets: {},
  };

  sections.forEach((section) => {
    const setName = section.title.toLowerCase().replace(/\s+/g, '-');
    figmaTokens.sets[setName] = {};

    section.tokens.forEach((token) => {
      const tokenKey = token.name.replace(/^--/, '').replace(/-/g, '/');
      figmaTokens.sets[setName][tokenKey] = {
        value: token.hex,
        type: 'color',
        description: `${section.description}`,
      };
    });
  });

  console.log('Figma Tokens Export:');
  console.log(JSON.stringify(figmaTokens, null, 2));

  return figmaTokens;
}

/**
 * Get token by name
 */
async function getToken(tokenName) {
  const tokensData = await loadDesignTokens();
  const { sections } = tokensData;

  for (const section of sections) {
    const token = section.tokens.find((t) => t.name === tokenName);
    if (token) {
      return token;
    }
  }

  console.warn(`Token not found: ${tokenName}`);
  return null;
}

/**
 * Search tokens by pattern
 */
async function searchTokens(pattern) {
  const tokensData = await loadDesignTokens();
  const { sections } = tokensData;
  const regex = new RegExp(pattern, 'i');
  const results = [];

  sections.forEach((section) => {
    section.tokens.forEach((token) => {
      if (regex.test(token.name) || regex.test(section.title)) {
        results.push({
          section: section.title,
          token: token.name,
          color: token.hex,
        });
      }
    });
  });

  return results;
}

